package com.gamehubstore.review_mscv.services;
import com.gamehubstore.review_mscv.client.OrderClient; import com.gamehubstore.review_mscv.models.Review; import com.gamehubstore.review_mscv.repositories.ReviewRepository; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ReviewServiceTest { @Test void acceptsOnlyPurchasedProduct(){ReviewRepository repo=mock(ReviewRepository.class);OrderClient orders=mock(OrderClient.class);ReviewService service=new ReviewService(repo,orders);Map<String,Object> detail=Map.of("idProducto",9);when(orders.findOrder(3L)).thenReturn(Map.of("userId",4,"estado","PAGADA","details",List.of(detail)));when(repo.existsByUserIdAndOrderIdAndProductId(4L,3L,9L)).thenReturn(false);when(repo.save(any())).thenAnswer(a->a.getArgument(0));Review r=new Review();r.setUserId(4L);r.setOrderId(3L);r.setProductId(9L);r.setRating(5);r.setComment("Excelente");assertSame(r,service.create(r));verify(repo).save(r);}
 @Test void rejectsProductNotOnOrder(){ReviewRepository repo=mock(ReviewRepository.class);OrderClient orders=mock(OrderClient.class);ReviewService service=new ReviewService(repo,orders);when(orders.findOrder(3L)).thenReturn(Map.of("userId",4,"estado","PAGADA","details",List.of(Map.of("idProducto",8))));Review r=new Review();r.setUserId(4L);r.setOrderId(3L);r.setProductId(9L);assertThrows(IllegalArgumentException.class,()->service.create(r));verify(repo,never()).save(any());}
}
